Set-Location -LiteralPath $PSScriptRoot
$msg = 'leads: a duplicate is a data-quality flag, not a suppression. The importer set status=dnc alongside is_duplicate on every duplicate branch, putting leads into the do-not-contact population for a bookkeeping reason - and the only endpoint that touched the flag DELETED the row, so a wrongly-flagged family record could be cleared only by destroying it. Decoupled: duplicates are flagged, never suppressed; call_restricted still sets DNC because that is a real suppression. Adds KEEP SEPARATE (POST /leads/id/not-duplicate) which resolves the flag, keeps both records, stamps who and when, writes an audit entry, deletes nothing, and restores a status ONLY when no real DNC reason exists - a STOP reply, a suppression entry or a manual flag all survive, and the check fails closed. Adds duplicate_reason, duplicate_match_field, duplicate_match_value so every future flag says what it matched and why, plus GET /leads/id/duplicate-explain which reconstructs the match live from the contact registry for rows flagged before reasons were stored. Adds two DRY-RUN-by-default repair passes: duplicate-dnc-repair lifts only the bug signature, tier-status-repair releases needs_tier_review rows that already have a valid tier and never releases a duplicate, a phoneless lead or a real DNC. UI gains Keep separate and Why on every flagged row.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
